function freeze(v){if(v&&typeof v==='object'&&!Object.isFrozen(v)){Object.freeze(v);for(const x of Object.values(v))freeze(x);}return v;}
freeze(data);
const clone=v=>JSON.parse(JSON.stringify(v)),byKey=new Map(data.topics.map(t=>[t.key,t]));
// No change to the catalogue, aliases, controls or existing source objects.
const sources={...base.sources};
for(const [id,value] of Object.entries(data.newSources)){
 if(Object.hasOwn(sources,id)&&JSON.stringify(sources[id])!==JSON.stringify(value))throw Error('Reviewed source ID collision');
 sources[id]=freeze(clone(value));
}
function build(input){
 const result=base.build(input),t=byKey.get(result?.topic);
 if(!t||result.ok!==true||result.mode!==t.mode||result.specificBodyAllowed===false)return result;
 const age=result.effectiveAgeBand||(input&&input.age)||'unknown';
 const baseline=t.baselineVariants?.[age]||t.baseline;
 // Replace only the reviewed ordinary body. Unknown or changed inherited content remains authoritative.
 const pending=new Map(baseline.map(s=>[s.title,[...s.items]])),extras=[],seen=new Set();
 for(const s of result.sections||[]){
  if(seen.has(s.title))return result;seen.add(s.title);
  const ordinary=pending.get(s.title),extra=[];
  if(!ordinary){extras.push({title:s.title,items:[...s.items]});continue;}
  for(const item of s.items){const at=ordinary.indexOf(item);if(at<0)extra.push(item);else ordinary.splice(at,1);}
  if(extra.length)extras.push({title:s.title,items:extra});
 }
 if([...pending.values()].some(items=>items.length))return result;
 const sections=clone(t.sections);
 // Preserve actually emitted contextual alarms, symptoms and clinician text verbatim, including action headings.
 const buckets={urgent:[],care:[],follow:[],notes:[]};
 for(let i=0;i<extras.length;i++){
  const s=extras[i],out={id:'contextual-'+i,title:s.title,items:s.items,itemIds:s.items.map((_,j)=>t.key+'.contextual.'+i+'.'+j)};
  const kind=/IMEDIATAMENTE|SOCORRO|URGENTE|EMERGÊNCIA|LIGUE 192/.test(s.title)?'urgent':s.title==='COMPLEMENTO DA CONSULTA'?'notes':/QUANDO REAVALIAR|CONTINUIDADE DO CUIDADO/.test(s.title)?'follow':'care';
  buckets[kind].push(out);
 }
 let alarmAt=0;while(alarmAt<sections.length&&['urgent','emergency'].includes(sections[alarmAt].id))alarmAt++;
 sections.splice(alarmAt,0,...buckets.urgent);
 let followAt=sections.findIndex(s=>s.id==='follow');if(followAt<0)followAt=sections.length;
 sections.splice(followAt,0,...buckets.care);
 followAt=sections.findIndex(s=>s.id==='follow');
 sections.splice(followAt<0?sections.length:followAt+1,0,...buckets.follow);
 sections.push(...buckets.notes);
 sections.forEach((s,i)=>s.number=i+1);
 const retired=data.retiredRefs[result.topic]||[];
 const refs=[...new Set([...(result.refs||[]).filter(id=>!retired.includes(id)),...t.refs])];
 if(refs.some(id=>!Object.hasOwn(sources,id)))return result;
 const firstBreak=result.text.indexOf('\n\n');if(firstBreak<0)return result;
 const header=result.text.slice(0,firstBreak),bullet=result.text.includes('\n• ')?'• ':'- ',footer='Estas orientações complementam a consulta e não substituem o tratamento prescrito.';
 const text=header+'\n\n'+sections.map((s,i)=>(i+1)+'. '+s.title+'\n'+s.items.map(x=>bullet+x).join('\n')).join('\n\n')+(result.text.endsWith(footer)?'\n\n'+footer:'');
 return {...result,sections,refs,text};
}
root.PaisGuide={...base,sources,build,reviewedSkinAccident20261007:{reviewedCards:data.topics.length,fullCatalogComplete:false}};
